pages=[]
def page(n,title,*paragraphs,tables=None,subsections=None):
 pages.append(dict(template_page=n,title=title,paragraphs=list(paragraphs),tables=tables or [],subsections=subsections or []))
def tab(headers,rows,title=None):return dict(headers=headers,rows=rows,title=title)
def sub(title,*paragraphs,tables=None):return dict(title=title,paragraphs=list(paragraphs),tables=tables or [])
contents=['I) ABOUT US IN BRIEF','Who we are, What we do','Vision, Mission','II) MARKET','Our Playfield, Market Opportunities','Our Market: Historical Data, Forecasts on growth','Industry Growth Drivers, Target Market','Competitor Analysis: Strengths (include funding received, if any) & Weaknesses','III) MORE ABOUT US','History & Shareholding','Services','Processes','Differentiators (+ logic of their sustainability)','Management Team','Organization Structure','IV) BUSINESS MODEL, FINANCIAL PROJECTIONS, INVESTMENT REQUIRED','Revenue Model','Rollout plan','Marketing Strategy: Promotion strategy, Online strategy','Initiatives in Pipeline (with investment numbers, where possible)','Financial Projections & Investment required']
page(1,'Your Business Name','Short Description: A student-developed ESP32 and Python workstation-security prototype combining fingerprint authentication, six environment checks and controlled credential release.','Prepared for the faculty funding review. Initial focus: accounting and finance SMEs in Gurugram. Planning horizon: FY 2027–28 to FY 2036–37.','We request an illustrative INR 44,470 engineering-pilot budget, released in stages. This funds learning and validation; ongoing commercial operations require a separate viability and funding decision. Figures labeled illustrative are classroom planning assumptions, not observed demand or test results.')
page(2,'Table of Contents','The contents headings below retain the teacher’s wording and order. The following document sections follow the template’s slide sequence; contents-only topics are included within the relevant sections. The final checklist provides a coverage guide.')
page(3,'I) ABOUT US – IN BRIEF','YOUR BUSINESS NAME: Cortex Sentinel','YOUR TAGLINE (IF ANY): Check the environment before releasing credentials. Proposed tagline for this plan.','Our immediate purpose is to turn a student prototype into a documented, testable engineering demonstrator. The business opportunity will be evaluated through controlled technical checks, local buyer discovery and measured delivery economics.','We will build two engineering units first and release the next eight only after documented acceptance checks. The ten engineering devices are not counted as paid sales. The base financial scenario currently loses money; the plan therefore makes commercialization conditional rather than assuming success.')
page(4,'Who We Are','Who we are, What we do: We are five computer-science students led by Kavyansh Kumar Baghel. We are developing a hardware-assisted workflow for sensitive Windows workstations. The team reports an ESP32/Python prototype; the refined-prototype description used for planning is an explicit scenario, not independent evidence of production readiness.',subsections=[sub('III) MORE ABOUT US','The following topics complete the contents-only requirements without changing the teacher’s later page sequence.'),sub('History & Shareholding','The project grew from a student prototype and earlier Cortex Sentinel coursework. PCB refinement and productization remain development work. For classroom modeling, an equal 20% interest for each of the five members is an illustrative ownership assumption only; no company incorporation, legal share issue or ownership agreement is asserted.'),sub('Services','The intended offer is a device with a Windows host application, setup guidance and an optional INR 500 annual updates-and-support service. Gemini analysis and AI subscriptions are excluded. Controlled recovery after restart/disconnect is selected as planned work.'),sub('Processes','Fingerprint authentication precedes six pre-flight checks: SSID, BSSID, USB baseline, process scan, path/masquerade integrity and final verification. Clean status permits credential injection. Continuous monitoring responds to configured network, USB and process events. On restart/reconnect, injection permission must reset and require fresh authentication and checks. Host-process failure cannot be assumed to enforce a Windows lock.')])
page(5,'Vision & Mission',subsections=[sub('Vision','Our proposed vision is to make understandable, affordable workstation-security workflows accessible to small professional firms handling sensitive information.'),sub('Mission','We will develop and test a locally supported hardware-and-software workflow, publish clear operating limits, and use measured customer and engineering evidence to decide whether commercial deployment is justified.'),sub('How the mission guides decisions','We prioritize recovery behavior, reliable integration and clear user instructions before adding more features. We will not claim general malware protection or guaranteed resistance to a compromised host. If customers prefer existing controls or unit economics remain weak, we will narrow the use case or retain the project as a demonstrator.')])
page(6,'II) OUR MARKET','MARKET OVERVIEW & FORECASTING OF OUR INDUSTRY','The product sits between identity authentication, workstation monitoring and endpoint-security tools. Windows Hello, FIDO security keys and endpoint protection address different parts of this workflow. Cortex Sentinel must demonstrate a useful complementary role rather than assume that combining checks creates superior protection. [1–3]','The selected initial discovery segment is Gurugram accounting/finance SMEs; legal SMEs and small banks are later candidates. Local institutional and district sources establish professional activity, not product demand. Banking requirements differ by regulated entity and cannot be treated as a universal SME purchase mandate. [4–5]','For the college exercise, the sizing model assumes 100 eligible local firms averaging five sensitive workstations each. These 500 seats are a constructed serviceable-market scenario, not a census. At a hypothetical INR 4,500 net device price, one-time device value is INR 22.50 lakh; at full annual subscription, service value is INR 2.50 lakh per year. Actual reachable buyers, permissions and purchasing intent must be tested.')
page(7,'Our Playfield','Graphic/Collage based overview of your industry','The industry overview below connects the authentication layer, the monitored workstation and the work required to deliver a supported product. Buyers may choose native Windows controls, stronger account authentication, endpoint protection, existing IT support, or no additional product.','Our launch boundary is an indoor Windows workstation with permission to install the host software and connect a USB device. Buyer authority, USB policy and compatibility are screening criteria. The prototype does not establish compatibility with every Windows environment or integration with enterprise sign-in.')
page(8,'Market Opportunities','Illustrative classroom opportunity sizing uses mutually exclusive firm categories within the 100-firm scenario; it is not researched market data.',tables=[tab(['Opportunity','Description','Assumed quantity','Illustrative device value'],[['1','Accounting practices: selected first discovery focus','60 firms × 5 seats = 300','INR 13.50 lakh'],['2','Other finance advisory SMEs','25 firms × 5 seats = 125','INR 5.625 lakh'],['3','Legal professional SMEs: later candidate','15 firms × 5 seats = 75','INR 3.375 lakh'],['Total','No overlap assumed across the three groups','100 firms / 500 seats','INR 22.50 lakh']])],subsections=[sub('Main complaints of customers: a), b), c)','The following are interview hypotheses, not customer quotations: a) authentication and workstation checks are fragmented; b) small firms have limited time to configure and explain controls; c) interruptions, recovery and support can make security tools difficult to use. Discovery must allow respondents to reject these hypotheses.','Quantification should be replaced by a documented local account list, eligibility checks and actual purchasing evidence. No opportunity value is booked as project revenue.')])
page(9,'Market – Historical Data & Forecast','Historical market size and growth: the table is a simulated baseline for the college exercise. It does not describe measured historical market size. Forecast market size and growth: the forward series is an illustrative addressable-seat scenario, separate from the project’s sales projections.',tables=[tab(['Year','Assumed firms','Seats at 5 per firm','Device value at INR 4,500'],[['2024 simulated',70,350,'INR 15.75 lakh'],['2025 simulated',85,425,'INR 19.125 lakh'],['2026 baseline',100,500,'INR 22.50 lakh'],['2027 scenario',115,575,'INR 25.875 lakh'],['2028 scenario',130,650,'INR 29.25 lakh'],['2029 scenario',145,725,'INR 32.625 lakh']])],subsections=[sub('Interpretation','The assumed increase is 15 firms a year. Corresponding seat-growth rates decline from 21.4% in 2025 to 11.5% in 2029 because the absolute increment is constant. This is model arithmetic, not an industry growth forecast. Project sales do not inherit this growth rate. Buyer conversion and production capacity are modeled separately.')])
page(10,'Industry Growth Drivers','Six candidate drivers describe business hypotheses and their operating consequences. They are not measured growth contributions.',tables=[tab(['Driver','Mechanism','Evidence to collect'],[['Driver 1: sensitive digital work','More sensitive records may increase interest in access controls','Buyer workflow and data-handling interviews'],['Driver 2: distributed work','Network changes may create monitoring needs','Remote-work frequency and existing policies'],['Driver 3: account-security awareness','Interest in stronger authentication may support evaluation','Existing MFA/Hello/FIDO use and gaps'],['Driver 4: IT capacity constraints','Limited configuration time may favor a supported offer','Installation time and IT ownership'],['Driver 5: assurance requirements','Specific regulated clients may require documented controls','Applicable official requirements; no universal mandate'],['Driver 6: component and software availability','Commodity hardware enables low-volume experimentation','Delivered quotes, availability and compatibility']])])
page(11,'Target market (Based on previous slides)',tables=[tab(['Segment','Description','Reason for targeting','Buying roles'],[['Segment A','Gurugram accounting/finance SMEs with sensitive Windows workstations','User-selected initial discovery priority; local evaluation can be bounded','User: professional; buyer: owner/IT lead; payer: firm — hypotheses'],['Segment B','Legal SMEs and selected small financial institutions','Later comparison where confidentiality and operating controls may matter','Partner/IT/procurement roles require validation']])],subsections=[sub('Qualification and initial reach','Screen for a real workflow problem, permission to install software and USB hardware, a named decision-maker, recovery requirements and an affordable evaluation. Begin with a proposed 5–8 exploratory conversations; no existing access, pipeline or appointments are claimed.'),sub('Geography and expansion','Gurugram comes first, followed conditionally by wider India and eventually international markets. No dates or sales are assigned merely because expansion is an aspiration. Small-bank evaluation requires entity-specific procurement and security checks. [5]')])
page(12,'Competitor Analysis',tables=[tab(['Company / alternative','Description','Strengths','Weaknesses or comparison limits'],[['Microsoft Windows Hello','Native managed sign-in/authentication','Established Windows integration','Different scope from external environment checks; configuration/licensing context matters'],['Yubico Security Key NFC','FIDO2/WebAuthn security key','Standardized account authentication','Does not represent the same monitoring bundle; Indian landed price not established'],['Microsoft Defender for Business','Endpoint-security subscription','Broader managed endpoint capabilities','Different product category and deployment costs; vendor price is not total ownership cost'],['Existing IT controls / do nothing','Keep current controls and procedures','Avoids new hardware and workflow change','May leave buyer-specific gaps; gaps must be demonstrated']])],subsections=[sub('Closest direct competitors','No exact like-for-like competitor has been established. The closest substitutes are native authentication combined with endpoint protection or an existing IT provider. The correct comparison is the customer’s complete alternative workflow.'),sub('Strengths (include funding received, if any) & Weaknesses','Competitor funding received is not used as a comparative advantage: no transaction-specific verified funding figure is established in this research. For the classroom comparison, funding is recorded as “not modeled”; publicly listed Microsoft and privately held product providers should not be assigned invented financing rounds. Official product claims are self-reported. [1–3]'),sub('Likely response and sustainability','Incumbents can bundle features, adjust prices and rely on installed relationships. We should respond with narrowly tested workflow value and support, not assume a permanent technical monopoly. Copyable commodity hardware offers little inherent protection; sustained advantage would require dependable integration, customer learning and trusted service.')])
page(13,'Why US – Our Differentiators',subsections=[sub('Differentiators (+ logic of their sustainability)','Our intended distinction is a visible fingerprint-led workflow linking six environment checks to credential release, supported by physical status feedback and planned recovery behavior. This is a design intention; its value over existing controls has not been demonstrated.','A sustainable advantage could develop through documented compatibility, reliable recovery, install/support knowledge and repeated customer feedback. These are execution goals, not current barriers to entry.'),sub('Illustrative results for the classroom example','Hypothetical examples only, not measured: 0 false accepts in 50 impostor attempts; 1 false rejection in 50 genuine attempts; 23 of 30 tool/configuration cases failing to capture a readable credential; a complete check sequence under eight seconds in an imagined run. A fictional 0/50 sample does not prove true zero FAR or general security.'),sub('Limits and response','Clipboard injection can still be exposed to clipboard capture or a compromised host. SSID/BSSID and filename/path rules cannot establish protection against all threats. Nitin will document threat-specific tests; King and Manas will correct integration failures before the second pilot tranche.')])
roles=[['Kavyansh Kumar Baghel','Lead; coordination, integration, milestones and shared discovery'],['Manas Sharma','Windows/Python application, monitoring and serial communication'],['King Kapoor','ESP32 firmware, sensors, wiring and hardware integration'],['Nitin Kumar','Test planning, security checks, results and technical documentation'],['Samarth Jain','Component costs, financial inputs, operations and shared discovery']]
page(14,'Team Profile','Management Team: The five members are CS majors. The responsibilities below are user-approved planning assignments. They do not establish prior experience, employment status or full-time availability.',tables=[tab(['Member','Accepted responsibility'],roles)],subsections=[sub('Organization Structure','Kavyansh coordinates the five workstreams and gates integration releases. Manas and King jointly own host-device interfaces; Nitin records independent acceptance evidence; Samarth maintains cost and cash records. Kavyansh and Samarth share discovery. Escalate unresolved safety/security integration to qualified external review.'),sub('Commitment and capability plan','For the classroom operating model, fixed operations use 40 hours/month at INR 250/hour in the base scenario. This is an aggregate costing assumption, not a commitment by any named person. Assembly and variable support labor are separately costed. Each member should demonstrate assigned tasks and agree availability before commercial promises are made.')])
page(15,'IV) BUSINESS MODEL & FINANCIAL Plan','IV) BUSINESS MODEL, FINANCIAL PROJECTIONS, INVESTMENT REQUIRED','We propose device revenue plus optional annual updates/support. The engineering pilot is a staged funding request to the teacher; the ten-year model is a sensitivity analysis for a possible later venture. It is not a prediction of sales or an approved commercial budget.','The model separates profit, cash timing and financing. The base scenario’s hardware-only break-even is 29 devices/month against assumed capacity of 20. Its annual pre-tax result remains negative through FY 2036–37. This is a reason to test the economics before commercialization, not conceal the deficit.')
page(16,'Revenue Generation Model',subsections=[sub('Revenue Model','Illustrative net retained prices are INR 4,500/device and INR 500/year for updates/support. The original price estimates have unresolved tax treatment; the model does not assert an applicable GST rate or recoverable input credit. Gemini revenue is excluded.','Base service attachment is 50% of new devices and annual renewal is 70%, both hypothetical. Annual prepayments are recognized over 12 months; remaining service obligations appear as deferred revenue. Base variable service cost is INR 300/account/year, leaving INR 200 before fixed maintenance.'),sub('Rollout plan','Plan for 1 Yr: Q1 engineering and discovery preparation; two units first, followed by eight only after checks. Q2 review buyer and cost evidence; Q3 permit limited evaluation only if safe and authorized; Q4 continue, narrow or stop commercialization according to economics. Plan for 3 Yrs: year 2 repeat delivery only with paying buyers and affordable support; year 3 consider wider India only after repeatable acquisition and positive contribution. Timing is conditional.'),sub('Marketing Strategy: Promotion strategy, Online strategy','Proposed promotion combines permission-based local discovery, demonstrations and a simple online explanation of product scope, limitations and support. No institutional partnership or acquired audience is claimed. Allocate INR 6,000/month from existing overhead to marketing/travel and eight operating hours (INR 2,000) to acquisition. At one, two or four new paying firms, illustrative CAC is INR 8,000, 4,000 or 2,000; these are scenario denominators, not forecasts.','With two devices per firm, base hardware contribution is INR 2,106 before acquisition and other overhead. Even the four-firm scenario leaves only INR 106 after allocated CAC, before remaining overhead. Do not deduct this allocation twice in the financial model.'),sub('Initiatives in Pipeline (with investment numbers, where possible)','Controlled recovery is planned first. An illustrative INR 5,000 recovery-development allocation may be explored within the existing INR 10,000 setup budget, subject to effort validation; it is not extra funding or a quote. Protected persistence and event history are deferred until scope, threat model and cost are established. No SIEM, mobile or cloud expansion is assumed.')])
canvas=[['Customer segments','Gurugram accounting/finance SMEs first; legal/bank candidates later'],['Value propositions','Fingerprint-led checks and controlled credential release; customer benefit to be tested'],['Channels','Permission-based discovery, demonstrations and a plain product website'],['Customer relationships','Setup guidance, recovery documentation and annual updates/support'],['Revenue streams','Illustrative INR 4,500 device; INR 500 annual service'],['Key resources','Five CS majors, ESP32/Python prototype, provisional ten-device pilot'],['Key activities','Integration, testing, discovery, assembly/QA, updates and support'],['Key partners','Potential component suppliers and qualified advisers; no agreements claimed'],['Cost structure','Materials, assembly, logistics, support, setup and recurring overhead']]
page(17,'Business Model Canvas','All nine blocks combine recorded project decisions and explicit planning hypotheses. Channels, conversion, supplier commitments, support workload and customer value require validation.',tables=[tab(['Block','Plan content'],canvas)])
page(18,'Projected Financials','Financial Projections & Investment required',tables=[tab(['Working device cost item','INR per device'],[['Listed parts and cable allowance',2347],['Wiring/driver/mounting allowance',250],['Assembly and QA allowance',400],['Inbound freight allocation',80],['Customer fulfillment',170],['Warranty/rework cash allowance',200],['Total variable allowance',3447]])],subsections=[sub('Revenue model, costs and break even calculations','At INR 4,500 net retained receipts, contribution is INR 1,053/device. Fixed base costs are INR 30,000/month: INR 10,000 operating labor plus INR 20,000 nonpay overhead. Hardware-only break-even = ceiling(30,000 / 1,053) = 29 devices/month. The assumed 20-device capacity cannot meet it. At 20 sales/month, one-driver thresholds are fixed costs no more than INR 21,060, price at least INR 4,947, or variable cost no more than INR 3,000. None is a proven achievable outcome.'),sub('Balance sheet drivers','The scenario holds one month of next-month device inventory, with terminal inventory retained at the last-month sales level; half a month of device revenue remains receivable in the base case. Annual service cash creates deferred revenue. Setup is expensed; no fixed-asset, debt-interest or income-tax schedule is asserted. Additional financing is an unmet requirement, not a secured facility.','The supplied teaching template’s chained-comparison break-even cell is replaced by a positive-contribution formula in the separate workbook. Zero or negative contribution produces no finite unit break-even; payback is evaluated using cumulative operating cash rather than a constant-profit shortcut.')])
